window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66c78cea9bf244de"]={"versions": [{"id": "FIG-66c78cea9bf244de", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Remote Event Communication Protocol (RecM) im AUTOSAR-Umfeld. Dargestellt wird der Prozess „Synchronize All Commands“ für ein Thin-Client-Szenario zwischen zwei Steuergeräte-Instanzen (Extended Dependent Secondary und Secondary) über ein zwischengelagertes Bussystem (BUS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Systemgrenzen mit ihren jeweiligen Software-Schichten:</p>\n<ul class=\"fig-list\"><li><strong>EXTENDED DEPENDENT SECONDARY</strong>: Enthält die Entitäten <code>RecM (Source)</code> als anfordernde/liefernde Komponente und den lokalen Kommunikationsstack <code>Comm. Stack</code>.\n</li><li><strong>SECONDARY</strong>: Enthält den lokalen Kommunikationsstack <code>Comm. Stack</code> und <code>RecM (Destination)</code> als empfangende/initiierende Komponente.\n</li><li><strong>BUS</strong>: Physisches/logisches Kommunikationsmedium zwischen den beiden Kommunikationsstacks.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen/Nachrichten:</p>\n<ul class=\"fig-list\"><li>Interne Trigger auf Empfängerseite: Selbstaufruf <code>Send Sync All Msg</code>.\n</li><li>Fehlersignalisierung/Kommunikation vom <code>Comm. Stack</code> bzw. Source an Destination.\n</li><li>Bus- und Stack-Nachrichten:\n<ul class=\"fig-list\"><li><code>RECM_MSG_MGMT_SYNC_ALL</code>: Steuerbefehl zur Gesamtsynchronisation.\n</li><li><code>RECM_MSG_STAT_VERS</code>: Statusmeldung Versionsinformation.\n</li><li><code>RECM_MSG_STAT_DTC</code>: Statusmeldung Diagnostic Trouble Codes.\n</li><li><code>RECM_MSG_STAT_MON_DIS</code>: Statusmeldung Monitor Disable / Statusüberwachung.\n</li><li><code>RECM_MSG_STAT_FLT_DET</code>: Statusmeldung Fehlererkennung (Fault Detection).\n</li><li><code>RECM_MSG_STAT_CALID_CVN</code>: Statusmeldung Kalibrierungs-ID und Calibration Verification Number.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in eine Auslösephase (alt-Block) und eine nachfolgende synchrone Datenübertragung:</p>\n<ol class=\"fig-list\"><li><strong>Trigger-Bedingungen (<code>alt</code>-Fragment)</strong> bei <code>RecM (Destination)</code>:\n<ul class=\"fig-list\"><li>Fall 1: <code>Recm Protocol compatible module: Initialization completed</code> führt zu internem <code>Send Sync All Msg</code>.\n</li><li>Fall 2: <code>Received Message Error</code> wird von <code>RecM (Source)</code> über <code>Comm. Stack</code> an die Destination-Seite gemeldet und führt dort zu <code>Send Sync All Msg</code>.\n</li><li>Fall 3: <code>Heartbeat Timeout</code> tritt lokal auf und löst intern <code>Send Sync All Msg</code> aus.\n</li></ul>\n</li><li><strong>Synchronisationsanforderung</strong>:\n<ul class=\"fig-list\"><li><code>RecM (Destination)</code> sendet <code>RECM_MSG_MGMT_SYNC_ALL</code> über seinen <code>Comm. Stack</code> über den <code>BUS</code> an den <code>Comm. Stack</code> des <code>EXTENDED DEPENDENT SECONDARY</code>, der die Nachricht an <code>RecM (Source)</code> weiterreicht.\n</li></ul>\n</li><li><strong>Sequenzielle Status-Antworten</strong>:\n<ul class=\"fig-list\"><li><code>RecM (Source)</code> antwortet nacheinander über seinen <code>Comm. Stack</code> und den <code>BUS</code> an <code>Comm. Stack</code> und <code>RecM (Destination)</code> mit folgenden Statusbotschaften:\n<ol class=\"fig-list\"><li><code>RECM_MSG_STAT_VERS</code>\n</li><li><code>RECM_MSG_STAT_DTC</code>\n</li><li><code>RECM_MSG_STAT_MON_DIS</code>\n</li><li><code>RECM_MSG_STAT_FLT_DET</code>\n</li><li><code>RECM_MSG_STAT_CALID_CVN</code>\n</li></ol>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsprotokoll zur vollständigen Zustandssynchronisation (<code>SYNC_ALL</code>) im Thin-Client-Szenario. Implementierende Module müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die drei disjunkten Trigger-Bedingungen (abgeschlossene Modulinitialisierung, Empfangsfehler und Heartbeat-Timeout) müssen jeweils die Neusynchronisation anstoßen.\n</li><li>Nach Empfang von <code>RECM_MSG_MGMT_SYNC_ALL</code> muss die Source-Instanz die definierte Reihenfolge der Statusübertragungen (Version, DTC, Monitor Disable, Fault Detection, CALID/CVN) deterministisch einhalten.\n</li><li>Beide Kommunikationsendpunkte müssen über die jeweiligen Kommunikationsstacks die Protokollnachrichten typkonform decodieren und serialisieren.\n</li></ul>"}, {"id": "FIG-12716abcdbe063c5", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Remote Event Communication Protocol (RecM) im AUTOSAR-Umfeld. Dargestellt wird der Prozess „Synchronize All Commands“ für ein Thin-Client-Szenario zwischen zwei Steuergeräte-Instanzen (Extended Dependent Secondary und Secondary) über ein zwischengelagertes Bussystem (BUS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Systemgrenzen mit ihren jeweiligen Software-Schichten:</p>\n<ul class=\"fig-list\"><li><strong>EXTENDED DEPENDENT SECONDARY</strong>: Enthält die Entitäten <code>RecM (Source)</code> als anfordernde/liefernde Komponente und den lokalen Kommunikationsstack <code>Comm. Stack</code>.\n</li><li><strong>SECONDARY</strong>: Enthält den lokalen Kommunikationsstack <code>Comm. Stack</code> und <code>RecM (Destination)</code> als empfangende/initiierende Komponente.\n</li><li><strong>BUS</strong>: Physisches/logisches Kommunikationsmedium zwischen den beiden Kommunikationsstacks.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen/Nachrichten:</p>\n<ul class=\"fig-list\"><li>Interne Trigger auf Empfängerseite: Selbstaufruf <code>Send Sync All Msg</code>.\n</li><li>Fehlersignalisierung/Kommunikation vom <code>Comm. Stack</code> bzw. Source an Destination.\n</li><li>Bus- und Stack-Nachrichten:\n<ul class=\"fig-list\"><li><code>RECM_MSG_MGMT_SYNC_ALL</code>: Steuerbefehl zur Gesamtsynchronisation.\n</li><li><code>RECM_MSG_STAT_VERS</code>: Statusmeldung Versionsinformation.\n</li><li><code>RECM_MSG_STAT_DTC</code>: Statusmeldung Diagnostic Trouble Codes.\n</li><li><code>RECM_MSG_STAT_MON_DIS</code>: Statusmeldung Monitor Disable / Statusüberwachung.\n</li><li><code>RECM_MSG_STAT_FLT_DET</code>: Statusmeldung Fehlererkennung (Fault Detection).\n</li><li><code>RECM_MSG_STAT_CALID_CVN</code>: Statusmeldung Kalibrierungs-ID und Calibration Verification Number.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in eine Auslösephase (alt-Block) und eine nachfolgende synchrone Datenübertragung:</p>\n<ol class=\"fig-list\"><li><strong>Trigger-Bedingungen (<code>alt</code>-Fragment)</strong> bei <code>RecM (Destination)</code>:\n<ul class=\"fig-list\"><li>Fall 1: <code>Recm Protocol compatible module: Initialization completed</code> führt zu internem <code>Send Sync All Msg</code>.\n</li><li>Fall 2: <code>Received Message Error</code> wird von <code>RecM (Source)</code> über <code>Comm. Stack</code> an die Destination-Seite gemeldet und führt dort zu <code>Send Sync All Msg</code>.\n</li><li>Fall 3: <code>Heartbeat Timeout</code> tritt lokal auf und löst intern <code>Send Sync All Msg</code> aus.\n</li></ul>\n</li><li><strong>Synchronisationsanforderung</strong>:\n<ul class=\"fig-list\"><li><code>RecM (Destination)</code> sendet <code>RECM_MSG_MGMT_SYNC_ALL</code> über seinen <code>Comm. Stack</code> über den <code>BUS</code> an den <code>Comm. Stack</code> des <code>EXTENDED DEPENDENT SECONDARY</code>, der die Nachricht an <code>RecM (Source)</code> weiterreicht.\n</li></ul>\n</li><li><strong>Sequenzielle Status-Antworten</strong>:\n<ul class=\"fig-list\"><li><code>RecM (Source)</code> antwortet nacheinander über seinen <code>Comm. Stack</code> und den <code>BUS</code> an <code>Comm. Stack</code> und <code>RecM (Destination)</code> mit folgenden Statusbotschaften:\n<ol class=\"fig-list\"><li><code>RECM_MSG_STAT_VERS</code>\n</li><li><code>RECM_MSG_STAT_DTC</code>\n</li><li><code>RECM_MSG_STAT_MON_DIS</code>\n</li><li><code>RECM_MSG_STAT_FLT_DET</code>\n</li><li><code>RECM_MSG_STAT_CALID_CVN</code>\n</li></ol>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsprotokoll zur vollständigen Zustandssynchronisation (<code>SYNC_ALL</code>) im Thin-Client-Szenario. Implementierende Module müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die drei disjunkten Trigger-Bedingungen (abgeschlossene Modulinitialisierung, Empfangsfehler und Heartbeat-Timeout) müssen jeweils die Neusynchronisation anstoßen.\n</li><li>Nach Empfang von <code>RECM_MSG_MGMT_SYNC_ALL</code> muss die Source-Instanz die definierte Reihenfolge der Statusübertragungen (Version, DTC, Monitor Disable, Fault Detection, CALID/CVN) deterministisch einhalten.\n</li><li>Beide Kommunikationsendpunkte müssen über die jeweiligen Kommunikationsstacks die Protokollnachrichten typkonform decodieren und serialisieren.\n</li></ul>"}], "trans": [{"from": "FIG-66c78cea9bf244de", "to": "FIG-12716abcdbe063c5", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
